// SAMPLE DATA – demo accounts for Customer Health Score workflow
// (not production customer data)
const accounts = [
  { account: 'Acme Retail EU', mrr: 4200, last_login_days: 2, active_users_pct: 78, open_tickets: 1, nps: 72, onboarding_completed: true, csm: 'Ana' },
  { account: 'Nordic Pricing Co', mrr: 8900, last_login_days: 18, active_users_pct: 35, open_tickets: 4, nps: 28, onboarding_completed: true, csm: 'Luis' },
  { account: 'Iberia SaaS Labs', mrr: 3100, last_login_days: 5, active_users_pct: 62, open_tickets: 0, nps: 65, onboarding_completed: true, csm: 'Ana' },
  { account: 'MedTech Hub', mrr: 12500, last_login_days: 45, active_users_pct: 12, open_tickets: 7, nps: 15, onboarding_completed: false, csm: 'Luis' },
  { account: 'Commerce Pulse', mrr: 5600, last_login_days: 3, active_users_pct: 81, open_tickets: 0, nps: 80, onboarding_completed: true, csm: 'Marta' },
  { account: 'Hotel Ops Pro', mrr: 7400, last_login_days: 12, active_users_pct: 48, open_tickets: 2, nps: 45, onboarding_completed: true, csm: 'Marta' },
  { account: 'FinServe Analytics', mrr: 9800, last_login_days: 1, active_users_pct: 90, open_tickets: 0, nps: 88, onboarding_completed: true, csm: 'Ana' },
  { account: 'EduLearn Cloud', mrr: 2200, last_login_days: 30, active_users_pct: 22, open_tickets: 5, nps: 30, onboarding_completed: false, csm: 'Luis' },
  { account: 'GreenSupply Chain', mrr: 6100, last_login_days: 7, active_users_pct: 55, open_tickets: 1, nps: 58, onboarding_completed: true, csm: 'Marta' },
  { account: 'TravelSync EMEA', mrr: 15000, last_login_days: 22, active_users_pct: 40, open_tickets: 3, nps: 40, onboarding_completed: true, csm: 'Ana' }
];
return accounts.map(a => ({ json: { ...a, data_source: 'SAMPLE DATA – Customer Health demo' } }));

// Rules-based score using Profile Config (NOT machine learning)
const cfg = $('Profile Config').first().json;
const a = $input.item.json;
const w = cfg.weights;
const f = cfg.signalFields;
const reasons = [];
const drivers = [];

function clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }

// Login
let loginPts = 0; let loginFlag = null;
const days = a[f.login_days];
if (days <= 7) loginPts = 25;
else if (days <= 14) loginPts = 18;
else if (days <= 30) loginPts = 8;
else { loginPts = 0; loginFlag = 'inactive >30d'; }
drivers.push({ signal: 'login', pts: loginPts, max: w.login, raw: days });
if (loginFlag) reasons.push(loginFlag);

// Adoption
const adoptVal = a[f.adoption];
const adoptPts = Math.round(clamp(adoptVal, 0, 100) / 100 * w.adoption);
drivers.push({ signal: 'adoption', pts: adoptPts, max: w.adoption, raw: adoptVal });
if (adoptVal < cfg.flags.adoption_below) reasons.push(cfg.flagLabels.adoption);

// Tickets
const t = a[f.tickets];
let ticketPts = 20;
if (t === 0) ticketPts = 20;
else if (t <= 2) ticketPts = 14;
else if (t <= 4) ticketPts = 7;
else { ticketPts = 0; reasons.push(cfg.flagLabels.tickets); }
drivers.push({ signal: 'tickets', pts: ticketPts, max: w.tickets, raw: t });

// NPS-like
const npsVal = a[f.nps];
const npsPts = Math.round(clamp(npsVal, 0, 100) / 100 * w.nps);
drivers.push({ signal: 'nps', pts: npsPts, max: w.nps, raw: npsVal });
if (npsVal < cfg.flags.nps_below) reasons.push(cfg.flagLabels.nps);

// Onboarding-like
const onboardVal = a[f.onboarding];
const onboardingPts = onboardVal ? w.onboarding : 0;
drivers.push({ signal: 'onboarding', pts: onboardingPts, max: w.onboarding, raw: onboardVal });
if (!onboardVal) reasons.push(cfg.flagLabels.onboarding);

let score = clamp(loginPts + adoptPts + ticketPts + npsPts + onboardingPts, 0, 100);
const redMax = cfg.thresholds.red;
const amberMax = cfg.thresholds.amber;
let risk_tier, playbook;
if (score < redMax) { risk_tier = 'Red'; playbook = cfg.playbooks.red; }
else if (score < amberMax) { risk_tier = 'Amber'; playbook = cfg.playbooks.amber; }
else { risk_tier = 'Green'; playbook = cfg.playbooks.green; }

if (reasons.length === 0) {
  if (score >= amberMax) reasons.push('healthy signals');
  else {
    const threshold = score < redMax ? redMax : amberMax;
    const sorted = [...drivers].sort((x, y) => x.pts - y.pts || (y.max - y.pts) - (x.max - x.pts));
    const weakest = sorted.slice(0, 4).map(d => {
      if (d.signal === 'login') return `login ${days}d→${d.pts}/${d.max}`;
      if (d.signal === 'adoption') return `adoption ${adoptVal}%→${d.pts}/${d.max}`;
      if (d.signal === 'tickets') return `tickets ${t}→${d.pts}/${d.max}`;
      if (d.signal === 'nps') return `NPS ${npsVal}→${d.pts}/${d.max}`;
      return `onboarding ${onboardVal ? 'done' : 'incomplete'}→${d.pts}/${d.max}`;
    }).join(', ');
    reasons.push(`aggregate risk: score ${score} below ${risk_tier} threshold ${threshold}; several signals mid-range (${weakest})`);
  }
}

const top_drivers = [...drivers].sort((a,b) => a.pts/a.max - b.pts/b.max).slice(0,3)
  .map(d => ({ signal: d.signal, pts: d.pts, max: d.max, utilization: Math.round((d.pts/d.max)*100) }));

return { json: { ...a, health_score: score, risk_tier, reason: reasons.join('; '), playbook, top_drivers, profile_id: cfg.profile_id, scored_at: new Date().toISOString() } };

const a = $input.item.json;
return {
  json: {
    alert_type: 'RED_RISK',
    priority: 'P1',
    account: a.account,
    mrr: a.mrr,
    health_score: a.health_score,
    reason: a.reason,
    assigned_csm: a.csm,
    playbook_action: a.playbook || 'schedule QBR / re-onboarding',
    channel: 'Slack #cs-risk (configure)',
    message: `🔴 RED RISK: ${a.account} (score ${a.health_score}). CSM ${a.csm}: ${a.playbook}. Reasons: ${a.reason}`
  }
};

const a = $input.item.json;
return {
  json: {
    alert_type: 'AMBER_NURTURE',
    priority: 'P2',
    account: a.account,
    mrr: a.mrr,
    health_score: a.health_score,
    reason: a.reason,
    assigned_csm: a.csm,
    playbook_action: a.playbook || 'nurture: check-in + feature adoption plan',
    task: `Create nurture task for ${a.account}: adoption plan + 15-min check-in`,
    message: `🟠 AMBER: ${a.account} (score ${a.health_score}). CSM ${a.csm}: nurture task.`
  }
};

const a = $input.item.json;
return {
  json: {
    alert_type: 'GREEN_EXPANSION',
    priority: 'P3',
    account: a.account,
    mrr: a.mrr,
    health_score: a.health_score,
    reason: a.reason,
    assigned_csm: a.csm,
    playbook_action: a.playbook || 'expansion candidate: upsell / referral ask',
    opportunity: `Flag ${a.account} as expansion candidate (MRR €${a.mrr})`,
    message: `🟢 GREEN: ${a.account} (score ${a.health_score}). Expansion candidate.`
  }
};

// Robust summary + revenue lens (reads builders by name — Merge-independent)
function itemsFrom(nodeName) {
  try { return $(nodeName).all().map(i => i.json); } catch (e) { return []; }
}
const cfg = (() => { try { return $('Profile Config').first().json; } catch (e) { return { profile_id: 'base', data_label: 'SAMPLE DATA' }; } })();
const red = itemsFrom('Build Red Risk Alert');
const amber = itemsFrom('Build Amber Nurture Task');
const green = itemsFrom('Flag Green Expansion');
const items = [...red, ...amber, ...green];
const sumMrr = arr => arr.reduce((s,a)=>s+(a.mrr||0),0);
const action_queue = items.map(a => {
  const riskWeight = a.alert_type === 'RED_RISK' ? 3 : a.alert_type === 'AMBER_NURTURE' ? 2 : 1;
  return {
    account: a.account,
    risk_tier: a.alert_type === 'RED_RISK' ? 'Red' : a.alert_type === 'AMBER_NURTURE' ? 'Amber' : 'Green',
    mrr: a.mrr,
    health_score: a.health_score,
    owner: a.assigned_csm,
    next_action: a.playbook_action,
    sla_hours: a.alert_type === 'RED_RISK' ? 24 : a.alert_type === 'AMBER_NURTURE' ? 72 : 168,
    priority_score: (a.mrr||0) * riskWeight,
    reason: a.reason,
  };
}).sort((a,b) => b.priority_score - a.priority_score);

const summary = {
  report: 'Weekly Customer Health Summary',
  profile_id: cfg.profile_id,
  data_label: cfg.data_label,
  scoring_model: 'rules-based (not ML)',
  generated_at: new Date().toISOString(),
  total_accounts: items.length,
  red_count: red.length,
  amber_count: amber.length,
  green_count: green.length,
  red_accounts: red.map(a => a.account),
  amber_accounts: amber.map(a => a.account),
  green_accounts: green.map(a => a.account),
  at_risk_mrr: sumMrr(red),
  revenue_lens: {
    by_tier: {
      Red: { accounts: red.length, mrr: sumMrr(red) },
      Amber: { accounts: amber.length, mrr: sumMrr(amber) },
      Green: { accounts: green.length, mrr: sumMrr(green) },
    },
    simulated_mrr_at_risk_sample_data: sumMrr(red),
    expansion_pipeline_green: {
      accounts: green.length,
      mrr: sumMrr(green),
      note: 'Green accounts flagged for upsell / referral (rules-based, SAMPLE DATA)',
    },
  },
  action_queue,
  notes: cfg.summary_notes || 'SAMPLE DATA only — rules-based demo (not ML). Simulated MRR at risk; Slack NoOp pending configuration.',
};
return [{ json: summary }];

